using System;using UnityEngine;using TMPro;
namespace IdleRestaurant{
 public sealed partial class RestaurantApp{
  double cleanupLastReward;float cleanupFeedbackUntil=-100;AudioClip cleanupBrush;
  public bool CanTapCleanup=>Game!=null&&Game.Family&&Game.State.introComplete&&page=="play"&&!modal;
  void BuildCleanupStatus(){var panel=Panel("Janitor status",body,new Vector2(.055f,.28f),new Vector2(.945f,.338f),Cream);panel.GetComponent<UnityEngine.UI.Image>().raycastTarget=false;var text=Text(panel,"",new Vector2(.025f,.06f),new Vector2(.975f,.94f),18,Ink,TextAlignmentOptions.Center);text.raycastTarget=false;var outline=panel.gameObject.AddComponent<UnityEngine.UI.Outline>();outline.effectColor=GuideYellow;outline.effectDistance=new Vector2(2,2);refresh.Add(()=>{panel.gameObject.SetActive(Game.State.introComplete);var job=Game.State.cleanupJob;bool first=!Game.State.cleanupGuideSeen&&Game.MessCount(Game.State.selected)>0;outline.enabled=first;if(Time.unscaledTime<cleanupFeedbackUntil){text.text=Economy.Money(cleanupLastReward);text.fontSize=28*(Game.State.largeText?1.12f:1);text.color=UpgradeGreen;return;}text.fontSize=24*(Game.State.largeText?1.12f:1);text.color=Ink;if(first)text.text="Tap dirt to call a janitor and earn bonus cash.";else if(job.active)text.text=job.outlet!=Game.State.selected?"Janitor working at "+catalog.outlets[job.outlet].title:job.phase==2?"JANITOR FINISHING · "+Economy.Money(job.reward):"JANITOR CLEANING · "+Math.Min(job.index+1,job.messIds.Length)+" / "+job.messIds.Length+" · "+Economy.Money(job.reward);else if(Game.CleanupWait>0)text.text="NEXT JANITOR IN "+Math.Ceiling(Game.CleanupWait)+"s"+(Game.State.queuedCleanup>=0?" · QUEUED":" · tap dirt to queue");else text.text=Game.MessCount(Game.State.selected)>0?"JANITOR READY · BONUS "+Economy.Money(Game.NetworkIncome()*Game.Balance.cleanupRewardMinutes):"Your restaurant is tidy";});}
  void ShowCleanupReward(int outlet,double amount){cleanupLastReward=amount;cleanupFeedbackUntil=Time.unscaledTime+3;Sound(upgrade);Notify(Economy.Money(amount));Save();}
  public void PlayCleanupBrush(){if(!Game.State.sfx)return;if(!cleanupBrush){int n=4410;var data=new float[n];uint seed=781;float filtered=0;for(int i=0;i<n;i++){seed=seed*1664525+1013904223;float white=(seed%65536)/32768f-1;filtered=.7f*filtered+.3f*white;data[i]=filtered*Mathf.Sin(i*Mathf.PI/n)*.12f;}cleanupBrush=AudioClip.Create("Soft janitor brush",n,1,22050,false);cleanupBrush.SetData(data,0);}audioSource.PlayOneShot(cleanupBrush,.45f);}
 }
}
